window.docContents[23].resolve({"/Preface/#Logical-Foundations--Preface--For-Instructors":{"contents":"A large compendium of exams from many offerings of CIS5000 (\"Software\nFoundations\") at the University of Pennsylvania can be found at\n<https://www.seas.upenn.edu/~cis5000/current/exams/index.html>. Until\n2026, the course was offered in Rocq, but the ideas behind the\nproblems are still relevant.\n\n","context":"Logical Foundations\u0009Preface","header":"1.5. For Instructors","id":"/Preface/#Logical-Foundations--Preface--For-Instructors"},"/Tactics/#Tactics":{"contents":"\n\nThis chapter could maybe use one or two more WORKINCLASS\ntags...\n\nGeneral comment: All the previous chapters have\nfelt pretty smooth. This one suddenly feels like we're throwing a\nhuge amount of information at them, with little scaffolding -- just\na bunch of miscellaneous tactics and examples.  Wish it flowed\nbetter, somehow.\n\n\n\nimport LF.Poly\nimport LF.CustomTactics\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Logical Foundations","header":"7. Tactics: More Basic Tactics","id":"/Tactics/#Tactics"}});